"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { ArticleLinkList } from "./help-center/article-link-list";
import { ArticlePage } from "./help-center/article-page";
import { HELP_ARTICLES, TOPICS, type TopicId } from "./help-center/data";
import { HelpSearch } from "./help-center/help-search";
import { TopicGrid } from "./help-center/topic-grid";
import { TopicView } from "./help-center/topic-view";
import { BuoyIcon, ChevronLeftIcon } from "./icons";

type View = { name: "home" } | { name: "topic"; topic: TopicId } | { name: "article"; id: string; from: View };

const DEPTH = { home: 0, topic: 1, article: 2 } satisfies Record<View["name"], number>;

const SLIDE = {
  enter: (direction: number) => ({ x: `${direction * 1.5}rem`, opacity: 0 }),
  center: { x: 0, opacity: 1 },
  exit: (direction: number) => ({ x: `${direction * -1.5}rem`, opacity: 0 }),
};

/**
 * A help centre for Fernhill. People search with live results, browse six
 * topics, and read an article with an outline that follows them and a
 * feedback question at the end. Views slide right going deeper, left coming back.
 */
export function HelpCenter({ className }: { className?: string }) {
  const [view, setView] = useState<View>({ name: "home" });
  const [direction, setDirection] = useState(1);
  const scroller = useRef<HTMLDivElement>(null);
  const reduceMotion = useReducedMotion();
  const titleId = useId();

  const go = (next: View) => {
    setDirection(DEPTH[next.name] >= DEPTH[view.name] ? 1 : -1);
    setView(next);
    scroller.current?.scrollTo({ top: 0 });
  };
  const openArticle = (id: string) => go({ name: "article", id, from: view.name === "article" ? view.from : view });

  const back = view.name === "article" ? view.from : { name: "home" as const };
  const backLabel = back.name === "topic" ? TOPICS.find((topic) => topic.id === back.topic)?.title : "Help home";
  const viewKey = view.name === "home" ? "home" : view.name === "topic" ? view.topic : view.id;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex items-center justify-between gap-3 border-b border-border px-5 py-3">
        <p className="flex items-center gap-2 text-sm font-semibold">
          <BuoyIcon aria-hidden="true" className="size-4 text-marketing-blue-ink" />
          Fernhill <span className="font-normal text-muted-foreground">Help</span>
        </p>
        <Button type="button" variant="outline" size="sm">
          Contact support
        </Button>
      </header>

      <div ref={scroller} className="scroll-fade-effect-y scrollbar-none relative h-136 overflow-y-auto overflow-x-hidden">
        <AnimatePresence mode="popLayout" initial={false} custom={direction}>
          <motion.div
            key={viewKey}
            custom={direction}
            variants={reduceMotion ? undefined : SLIDE}
            initial={reduceMotion ? { opacity: 0 } : "enter"}
            animate={reduceMotion ? { opacity: 1 } : "center"}
            exit={reduceMotion ? { opacity: 0 } : "exit"}
            transition={{ duration: 0.24, ease: [0.2, 0, 0, 1] }}
            className="px-5 pb-8"
          >
            {view.name === "home" ? (
              <div className="flex flex-col gap-10">
                <div className="flex flex-col items-center gap-5 pt-10 text-center">
                  <h2 id={titleId} className="text-3xl font-semibold tracking-tight text-balance @lg:text-4xl">
                    What can we help you with?
                  </h2>
                  <HelpSearch onOpen={openArticle} />
                </div>
                <section aria-labelledby={`${titleId}-topics`} className="flex flex-col gap-3">
                  <h3 id={`${titleId}-topics`} className="text-sm font-medium text-muted-foreground">
                    Browse by topic
                  </h3>
                  <TopicGrid onOpen={(topic) => go({ name: "topic", topic })} />
                </section>
                <section aria-labelledby={`${titleId}-popular`} className="flex flex-col gap-1">
                  <h3 id={`${titleId}-popular`} className="text-sm font-medium text-muted-foreground">
                    Popular articles
                  </h3>
                  <ArticleLinkList label="Popular articles" articles={HELP_ARTICLES.filter((article) => article.popular)} onOpen={openArticle} />
                </section>
              </div>
            ) : (
              <div className="flex flex-col gap-6 pt-4">
                <Button type="button" variant="ghost" size="sm" className="self-start" onClick={() => go(back)}>
                  <ChevronLeftIcon aria-hidden="true" />
                  {backLabel}
                </Button>
                {view.name === "topic" ? (
                  <TopicView topic={view.topic} onOpen={openArticle} titleId={titleId} />
                ) : (
                  <>
                    <h2 id={titleId} className="sr-only">
                      Fernhill help
                    </h2>
                    {HELP_ARTICLES.filter((article) => article.id === view.id).map((article) => (
                      <ArticlePage key={article.id} article={article} scroller={scroller} />
                    ))}
                  </>
                )}
              </div>
            )}
          </motion.div>
        </AnimatePresence>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

import { Button } from "@/components/ui/button";

import { ChevronRightIcon } from "../../parts/icons";
import type { HelpArticle } from "./data";

/** Props for a list of article links. */
export interface ArticleLinkListProps {
  articles: HelpArticle[];
  onOpen: (articleId: string) => void;
  label: string;
}

/** A plain list of articles, each a full-width row that opens the article. */
export function ArticleLinkList({ articles, onOpen, label }: ArticleLinkListProps) {
  return (
    <ul aria-label={label} className="flex flex-col gap-1">
      {articles.map((article) => (
        <li key={article.id}>
          <Button
            type="button"
            variant="ghost"
            size="sm"
            onClick={() => onOpen(article.id)}
            className="group w-full justify-start text-left whitespace-normal"
          >
            <span className="flex w-full items-center gap-3 px-3 py-3 font-normal">
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="text-sm font-medium">{article.title}</span>
                <span className="text-xs text-muted-foreground">{article.summary}</span>
              </span>
              <span className="shrink-0 text-xs tabular-nums text-muted-foreground">{article.minutes} min</span>
              <ChevronRightIcon aria-hidden="true" className="size-4 shrink-0 text-muted-foreground motion-safe:transition-transform group-hover:translate-x-0.5" />
            </span>
          </Button>
        </li>
      ))}
    </ul>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

