"use client";

import { motion, useReducedMotion } from "motion/react";
import { type RefObject, useEffect, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

import { ArticleFeedback } from "./article-feedback";
import { type HelpArticle, TOPICS } from "./data";

/** Props for one article. */
export interface ArticlePageProps {
  article: HelpArticle;
  /** The box that scrolls, so the outline can follow the section being read. */
  scroller: RefObject<HTMLDivElement | null>;
}

/**
 * One article with its outline beside it. The outline's marker follows the
 * section being read, and a click on an outline entry scrolls to it.
 */
export function ArticlePage({ article, scroller }: ArticlePageProps) {
  const [current, setCurrent] = useState(article.sections[0]?.id ?? "");
  const reduceMotion = useReducedMotion();
  const heading = useRef<HTMLHeadingElement>(null);
  const markerId = useId();
  const sectionId = (id: string) => `${markerId}-${id}`;
  const topic = TOPICS.find((item) => item.id === article.topic);

  useEffect(() => {
    heading.current?.focus({ preventScroll: true });
  }, []);

  // The section being read is the last one whose top has passed a line a quarter down the box.
  useEffect(() => {
    const box = scroller.current;
    if (!box) return;
    const onScroll = () => {
      const line = box.getBoundingClientRect().top + box.clientHeight * 0.25;
      let reading = article.sections[0]?.id ?? "";
      for (const section of article.sections) {
        const node = document.getElementById(sectionId(section.id));
        if (node && node.getBoundingClientRect().top <= line) reading = section.id;
      }
      // At the very bottom, the last section counts as read even if it is short.
      if (box.scrollTop + box.clientHeight >= box.scrollHeight - 4) reading = article.sections[article.sections.length - 1]?.id ?? reading;
      setCurrent(reading);
    };
    box.addEventListener("scroll", onScroll, { passive: true });
    return () => box.removeEventListener("scroll", onScroll);
  });

  const jump = (id: string) => {
    document.getElementById(sectionId(id))?.scrollIntoView({ behavior: reduceMotion ? "auto" : "smooth", block: "start" });
    setCurrent(id);
  };

  return (
    <article className="grid gap-8 @3xl:grid-cols-[12rem_1fr]">
      <nav aria-label="On this page" className="@3xl:sticky @3xl:top-0 @3xl:self-start">
        <p className="pb-2 text-xs font-medium text-muted-foreground">On this page</p>
        <ul className="flex flex-col border-l border-border">
          {article.sections.map((section) => {
            const reading = section.id === current;
            return (
              <li key={section.id} className="relative">
                {reading ? (
                  <motion.span
                    layoutId={markerId}
                    aria-hidden="true"
                    transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 42 }}
                    className="absolute inset-y-1 -left-px w-0.5 rounded-full bg-chart-1"
                  />
                ) : null}
                <a
                  href={`#${sectionId(section.id)}`}
                  aria-current={reading ? "location" : undefined}
                  onClick={(event) => {
                    event.preventDefault();
                    jump(section.id);
                  }}
                  className={cn(
                    "block rounded-md py-1.5 pl-3 text-sm outline-none focus-visible:ring-2 focus-visible:ring-ring",
                    reading ? "font-medium text-foreground" : "text-muted-foreground hover:text-foreground",
                  )}
                >
                  {section.heading}
                </a>
              </li>
            );
          })}
        </ul>
      </nav>
      <div className="flex min-w-0 flex-col gap-6">
        <header className="flex flex-col gap-1">
          <h3 ref={heading} tabIndex={-1} className="rounded-sm text-2xl font-semibold tracking-tight outline-none focus-visible:ring-2 focus-visible:ring-ring">
            {article.title}
          </h3>
          <p className="text-sm text-muted-foreground">
            {topic?.title}, {article.minutes} minute read
          </p>
        </header>
        {article.sections.map((section) => (
          <section key={section.id} id={sectionId(section.id)} aria-labelledby={`${sectionId(section.id)}-title`} className="flex scroll-mt-4 flex-col gap-2">
            <h4 id={`${sectionId(section.id)}-title`} className="text-base font-semibold">
              {section.heading}
            </h4>
            {section.paragraphs.map((paragraph) => (
              <p key={paragraph} className="text-sm leading-relaxed text-foreground">
                {paragraph}
              </p>
            ))}
          </section>
        ))}
        <ArticleFeedback />
      </div>
    </article>
  );
}

