"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { SearchField } from "../shared/search-field";
import { SUGGESTIONS } from "./data";
import { searchArticles } from "./search";

/** Props for the help centre search. */
export interface HelpSearchProps {
  onOpen: (articleId: string) => void;
}

/**
 * A search field with results that drop in under it. Up and Down move the
 * highlight, Enter opens it, and Escape clears the field, then leaves it.
 * Suggested words under the field fill it in.
 */
export function HelpSearch({ onOpen }: HelpSearchProps) {
  const [query, setQuery] = useState("");
  const [active, setActive] = useState(0);
  const [focused, setFocused] = useState(false);
  const field = useRef<HTMLInputElement>(null);
  const reduceMotion = useReducedMotion();
  const fieldId = useId();
  const listId = useId();
  const results = searchArticles(query);
  const expanded = focused && query.trim().length > 0;
  const highlighted = Math.min(active, Math.max(0, results.length - 1));

  const update = (next: string) => {
    setQuery(next);
    setActive(0);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      if (results.length === 0) return;
      setActive((highlighted + (event.key === "ArrowDown" ? 1 : -1) + results.length) % results.length);
    } else if (event.key === "Enter") {
      event.preventDefault();
      const article = results[highlighted];
      if (article) onOpen(article.id);
    } else if (event.key === "Escape") {
      event.preventDefault();
      if (query) update("");
      else field.current?.blur();
    }
  };

  return (
    <div className="flex w-full max-w-xl flex-col items-center gap-3">
      <div className="relative w-full">
        <label htmlFor={fieldId} className="sr-only">
          Search the help centre
        </label>
        <SearchField
          size="lg"
          ref={field}
          id={fieldId}
          role="combobox"
          aria-expanded={expanded}
          aria-controls={listId}
          aria-autocomplete="list"
          aria-activedescendant={expanded && results.length > 0 ? `${listId}-${highlighted}` : undefined}
          value={query}
          onChange={(event) => update(event.target.value)}
          onKeyDown={onKeyDown}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
          placeholder="Search, like reminders or waitlist"
        />
        <AnimatePresence>
          {expanded ? (
            <motion.ul
              key="results"
              id={listId}
              role="listbox"
              aria-label="Matching articles"
              initial={reduceMotion ? { opacity: 0 } : { opacity: 0, scale: 0.98, y: -4 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 0.16, ease: [0.2, 0, 0, 1] }}
              className="absolute inset-x-0 top-full origin-top z-20 mt-2 flex flex-col overflow-hidden rounded-xl border border-border bg-popover p-1 text-popover-foreground shadow-lg backdrop-blur-md"
            >
              {results.map((article, index) => (
                <li
                  key={article.id}
                  id={`${listId}-${index}`}
                  role="option"
                  aria-selected={index === highlighted}
                  // Keep focus in the field, so the list never steals it on a click.
                  onMouseDown={(event) => event.preventDefault()}
                  onMouseEnter={() => setActive(index)}
                  onClick={() => onOpen(article.id)}
                  className={cn("flex cursor-pointer flex-col rounded-lg px-3 py-2 text-left", index === highlighted && "bg-muted")}
                >
                  <span className="text-sm font-medium">{article.title}</span>
                  <span className="truncate text-xs text-muted-foreground">{article.summary}</span>
                </li>
              ))}
              {results.length === 0 ? <li className="px-3 py-3 text-sm text-muted-foreground">No article matches. Try another word.</li> : null}
            </motion.ul>
          ) : null}
        </AnimatePresence>
      </div>
      <p role="status" className="sr-only">
        {expanded ? `${results.length} ${results.length === 1 ? "result" : "results"}` : ""}
      </p>
      <div className="flex flex-wrap items-center justify-center gap-2 text-sm text-muted-foreground">
        Try
        {SUGGESTIONS.map((word) => (
          <Button
            key={word}
            type="button"
            variant="outline"
            size="sm"
            onClick={() => {
              update(word);
              field.current?.focus();
            }}
          >
            {word}
          </Button>
        ))}
      </div>
    </div>
  );
}

