import { HELP_ARTICLES, type HelpArticle } from "./data";

/**
 * The articles that match every word of a query, title matches first. It
 * searches titles, summaries and section headings.
 */
export function searchArticles(query: string): HelpArticle[] {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  if (words.length === 0) return [];
  const haystack = (article: HelpArticle) => `${article.title} ${article.summary} ${article.sections.map((section) => section.heading).join(" ")}`.toLowerCase();
  return HELP_ARTICLES.filter((article) => words.every((word) => haystack(article).includes(word))).sort(
    (a, b) => Number(words.some((word) => b.title.toLowerCase().includes(word))) - Number(words.some((word) => a.title.toLowerCase().includes(word))),
  );
}

